import{_ as a,o as r,c as o,a2 as e}from"./chunks/framework.Bx7X8BVG.js";const g=JSON.parse('{"title":"管理面板","description":"","frontmatter":{},"headers":[],"relativePath":"guide/panel.md","filePath":"guide/panel.md","lastUpdated":1791341338000}'),l={name:"guide/panel.md"};function d(n,t,s,i,h,c){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="管理面板" tabindex="-1">管理面板 <a class="header-anchor" href="#管理面板" aria-label="Permalink to &quot;管理面板&quot;">​</a></h1><p>本文基于 v1.8.1。左侧页面包括：首页、系统配置、Tunnel 列表、API 凭证、运行日志、用户管理、关于。Docker 与桌面端的端口、数据目录和升级方式不同，见 <a href="/cloudflare-tunnel-manager/guide/">快速开始</a>。</p><h2 id="首页" tabindex="-1">首页 <a class="header-anchor" href="#首页" aria-label="Permalink to &quot;首页&quot;">​</a></h2><p>一眼看清现状：<strong>在线隧道数 / 隧道总数 / 边缘连接数 / 运行时长</strong>，下面是隧道卡片一览（名称、域名、本地服务、在线状态）。</p><p>尚未配置 Cloudflare 凭据时，顶部会提示并给出教程入口。</p><h2 id="tunnel-列表" tabindex="-1">Tunnel 列表 <a class="header-anchor" href="#tunnel-列表" aria-label="Permalink to &quot;Tunnel 列表&quot;">​</a></h2><p>这是最常用的页面。</p><h3 id="创建与启停" tabindex="-1">创建与启停 <a class="header-anchor" href="#创建与启停" aria-label="Permalink to &quot;创建与启停&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><strong>新建 Tunnel</strong></td><td>输入名称即可，会在 Cloudflare 云端创建隧道（不会自动建 DNS）</td></tr><tr><td><strong>连接 / 断开</strong></td><td>单条隧道独立进程，<strong>多条可以同时在线</strong></td></tr><tr><td><strong>自启开关</strong></td><td>面板服务启动后自动连接；桌面端不等同于操作系统开机启动</td></tr><tr><td><strong>删除</strong></td><td>同时清理本地进程与云端隧道</td></tr></tbody></table><p>每条隧道会显示两个可点击的链接：</p><ul><li><strong>域名：</strong> <code>https://nas.example.com</code> —— 新窗口打开你的服务</li><li><strong>本地：</strong> <code>http://192.168.1.10:5000</code> —— 新窗口打开内网地址（在 NAS 所在网络内可用）</li></ul><h3 id="路由规则" tabindex="-1">路由规则 <a class="header-anchor" href="#路由规则" aria-label="Permalink to &quot;路由规则&quot;">​</a></h3><p>点「路由」配置「域名 → 内网服务」的映射：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>域名</td><td>要暴露的公网域名，如 <code>nas.example.com</code></td></tr><tr><td>服务</td><td>内网地址，如 <code>http://192.168.1.10:5000</code></td></tr></tbody></table><p>保存后会自动在 Cloudflare 创建 <strong>DNS CNAME</strong> 记录（橙云代理），所以：</p><ul><li>边缘自动提供 <strong>HTTPS</strong>，不用自己申请证书</li><li>隐藏了你的真实出口 IP</li></ul><div class="tip custom-block"><p class="custom-block-title">同一个内网服务可以挂多个域名</p><p>一条隧道的规则列表里可以加多条规则，指向同一个内网服务。所以「随机域名 + 自定义域名」同时挂在一个服务上完全没问题——这正是调试期常用的做法：随机域名用来临时验证，跑通了再换成正式域名。</p></div><h3 id="随机子域名" tabindex="-1">随机子域名 <a class="header-anchor" href="#随机子域名" aria-label="Permalink to &quot;随机子域名&quot;">​</a></h3><p>先在「<strong>系统配置 → 默认域名</strong>」里填好主域名（如 <code>example.com</code>），之后在路由弹窗里点「<strong>🎲</strong>」就能生成一个随机二级域名。</p><p>生成的是「随机词 + 你的域名」形式，而不是一串纯数字，看着更像正常站点。</p><h2 id="设备识别与分组" tabindex="-1">设备识别与分组 <a class="header-anchor" href="#设备识别与分组" aria-label="Permalink to &quot;设备识别与分组&quot;">​</a></h2><p>如果你在<strong>多台设备</strong>（例如服务器1、服务器2、NAS3）上装了同一个账号，隧道列表会自动按设备归类：</p><ul><li>顶部有一条<strong>筛选标签栏</strong>，第一行是<strong>设备</strong>（🏠 本机 / ☁️ 其他设备）</li><li>第二行是<strong>分组</strong>（默认「未分组」）</li><li>点标签即可筛选，再点一次取消</li></ul><p>分组名和设备显示名都可以自己改：</p><ul><li><strong>改设备显示名</strong>：「系统配置 → 本设备名称」</li><li><strong>改分组名</strong>：在筛选条上点分组标签旁的编辑按钮，会把这个分组下所有隧道一起改名</li></ul><div class="info custom-block"><p class="custom-block-title">为什么能看到其他设备的隧道？</p><p>隧道信息存在 Cloudflare 云端，所有用同一账号凭据的面板都会看到全量列表。「本机 / 其他设备」标记是根据进程实际运行的位置判断的——本机跑着的隧道才能真正操作。</p></div><h2 id="用户管理" tabindex="-1">用户管理 <a class="header-anchor" href="#用户管理" aria-label="Permalink to &quot;用户管理&quot;">​</a></h2><blockquote><p>仅管理员可见。</p></blockquote><ul><li><strong>审核注册</strong>：新用户注册后处于待审核状态，管理员通过后才能登录</li><li><strong>启用 / 禁用</strong>：禁用会<strong>立即踢下线</strong>（当前会话失效）</li><li><strong>重置密码 / 删除用户</strong></li><li><strong>备注</strong>：给用户加个说明（例如「客厅笔记本」「老爸的手机」），仅管理员可见</li><li><strong>注册开关</strong>：关闭后登录页不再显示注册入口</li></ul><p>普通用户能做什么：查看和操作<strong>自己的</strong>隧道，看不到其他用户创建的隧道，也进不了用户管理和 API 凭证页。</p><h3 id="忘记管理员密码" tabindex="-1">忘记管理员密码 <a class="header-anchor" href="#忘记管理员密码" aria-label="Permalink to &quot;忘记管理员密码&quot;">​</a></h3><p>在 NAS 上给容器加环境变量 <code>ADMIN_PASSWORD</code>，然后：</p><ul><li>用户名填 <code>master</code> 或留空，密码填 <code>ADMIN_PASSWORD</code> 的值</li><li>登录后可在用户管理里重置任意用户密码</li></ul><h2 id="系统配置" tabindex="-1">系统配置 <a class="header-anchor" href="#系统配置" aria-label="Permalink to &quot;系统配置&quot;">​</a></h2><p>分三块：</p><table tabindex="0"><thead><tr><th>卡片</th><th>内容</th></tr></thead><tbody><tr><td><strong>站点设置</strong></td><td>站点名称自定义、禁止搜索引擎收录开关</td></tr><tr><td><strong>Cloudflare 账号</strong></td><td>Account ID、API Token（测试连接后保存）、折叠的获取教程</td></tr><tr><td><strong>连接参数</strong></td><td>连接协议（QUIC / HTTP2）、边缘 IP 版本（IPv4 / IPv6）、默认域名</td></tr></tbody></table><h3 id="站点设置" tabindex="-1">站点设置 <a class="header-anchor" href="#站点设置" aria-label="Permalink to &quot;站点设置&quot;">​</a></h3><ul><li><strong>站点名称</strong>：改这里会同步更新浏览器标签页标题、侧边栏品牌名、登录页标题。最长 32 字，留空恢复默认。</li><li><strong>禁止搜索引擎收录</strong>：默认开启，详见 <strong><a href="/cloudflare-tunnel-manager/guide/security#三层反收录">安全与公网暴露</a></strong>。</li></ul><h3 id="连接参数怎么选" tabindex="-1">连接参数怎么选 <a class="header-anchor" href="#连接参数怎么选" aria-label="Permalink to &quot;连接参数怎么选&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>建议</th></tr></thead><tbody><tr><td>协议</td><td>默认 <code>QUIC</code>（UDP）。若网络屏蔽 UDP 导致连不上，改成 <code>HTTP2</code></td></tr><tr><td>边缘 IP 版本</td><td>默认 <code>IPv4</code>。纯 IPv6 环境选 <code>IPv6</code>，不确定留 <code>auto</code></td></tr><tr><td>默认域名</td><td>填你的主域名，用于一键随机子域名</td></tr></tbody></table><h2 id="运行日志" tabindex="-1">运行日志 <a class="header-anchor" href="#运行日志" aria-label="Permalink to &quot;运行日志&quot;">​</a></h2><p>每条隧道独立日志区，支持：</p><ul><li>关键字过滤</li><li>自动刷新开关</li><li>异常退出时<strong>真正的错误行会被提取置顶</strong>，不用在几十行日志里翻</li></ul><h2 id="关于" tabindex="-1">关于 <a class="header-anchor" href="#关于" aria-label="Permalink to &quot;关于&quot;">​</a></h2><ul><li><strong>项目信息</strong>：版本号、提交号、运行环境、数据目录、面板目录、仓库链接</li><li><strong>版本更新</strong>：检测更新 → 手动确认 → 一键更新（详见 <strong><a href="/cloudflare-tunnel-manager/guide/update">更新与国内加速</a></strong>）</li><li><strong>更新源设置</strong>：默认已内置国内镜像自动切换，一般无需修改</li></ul>',45)])])}const p=a(l,[["render",d]]);export{g as __pageData,p as default};
